(() => {
  const btn=document.querySelector('#readBtn'),host=document.querySelector('#interactiveResult'); if(!btn||!host)return;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const meaning={紫微:'主導、整合資源及承擔責任；失衡時容易控制過多。',貪狼:'探索、人際、慾望及多才；要避免分心。',天機:'思考、變通、策劃及資訊流動；失衡時容易反覆。',太陰:'感受、照顧、資產及內在安全感；要留意情緒內收。',巨門:'語言、質疑、研究及辯證；要留意誤會與口舌。',天相:'協調、公平、制度及支援；要留意過度顧全。',天梁:'保護、原則、長輩及解難；要留意說教。',廉貞:'界線、慾望、原則及創意；要留意灰色地帶。',七殺:'突破、決斷、競爭及高壓處理；要留意硬撐。',天同:'和氣、調節壓力及舒適節奏；要留意拖延。',武曲:'執行、財務、紀律及結果；要留意過硬。',破軍:'改革、拆舊立新及重新開始；要先計算代價。',太陽:'公開性、付出、領導及承擔；要留意過勞。',天府:'資源管理、穩定、保存及整合；要留意保守。',右弼:'協作及助力；分清幫忙與代你承擔。',文曲:'審美、技巧及情感表達；要留意誤會。',文昌:'學習、文書及邏輯表達；要留意文件細節。',天魁:'提攜及機會；主動展示能力。',天鉞:'引薦及資源；維持專業信任。',祿存:'資源累積及穩定；避免只守不動。',擎羊:'壓力及切割；避免硬碰硬。',陀羅:'拖延及暗阻；預留時間。',火星:'突發及急進；控制衝動。',鈴星:'焦慮及突然變化；先穩住節奏。',地空:'落空及想像；用證據驗證。',地劫:'損耗及資源破口；先定風險上限。',天馬:'移動、轉換及外部機會；要管理節奏。'};
  const palNames=['命宮','兄弟','夫妻','子女','財帛','疾厄','遷移','僕役','官祿','田宅','福德','父母'];
  const terms={三方四正:'命宮與財帛、官祿、遷移互相會照的整體結構。',借對宮:'本宮沒有主星時參考對宮及三方四正。',化祿:'資源、順勢及容易得到的好處。',化權:'責任、控制力及推動力，也代表壓力。',化科:'名聲、方法、學習及被看見。',化忌:'卡點、執著、誤解或需要補證據的位置。'};
  let ps=[];
  const drawer=(title,text)=>{const d=host.querySelector('#termDrawer');d.hidden=false;d.innerHTML=`<button class="term-close" aria-label="關閉解釋">×</button><b>${esc(title)}</b><p>${esc(text)}</p>`;d.querySelector('button').onclick=()=>d.hidden=true;};
  const show=i=>{const p=ps[i],detail=host.querySelector('#palaceDetail'),name=p.name,stars=p.stars||[];detail.innerHTML=`<p class="eyebrow">PALACE ${String(i+1).padStart(2,'0')}</p><h4>${esc(name)}宮</h4><p>${esc(name==='命宮'?'代表本人性格、外在表現、人生主軸及面對事情的方式。':'先看宮位主題，再看星曜如何在此生活領域表現。')}</p><div class="star-list"><b>星曜（${stars.length}）</b><div>${stars.map(s=>`<button class="star-chip" data-star="${esc(s)}">${esc(s)}</button>`).join('')}</div></div><div class="star-explain-list">${stars.map(s=>`<div class="star-explain"><b>${esc(s)}</b><span>${esc(meaning[s]||'要連同宮位、亮度、四化、會照及流限判讀。')}</span></div>`).join('')}</div><div class="term-list">${Object.keys(terms).map(t=>`<button class="term-chip" data-term="${t}">${t}</button>`).join('')}</div>`;host.querySelectorAll('.palace-card').forEach((c,n)=>c.classList.toggle('is-selected',n===i));detail.querySelectorAll('.star-chip').forEach(c=>c.onclick=()=>drawer(c.dataset.star,`${meaning[c.dataset.star]||'星曜要配合宮位解讀。'} 解讀方法：先看落宮生活範圍，再核對亮度、四化、會照及流年，最後落實到現實行動。`));detail.querySelectorAll('.term-chip').forEach(c=>c.onclick=()=>drawer(c.dataset.term,terms[c.dataset.term]));};
  const render=()=>{if(document.querySelector('.method.active')?.dataset.name!=='紫微斗數')return;const actual=window.__ziweiDisplayPalaces||[];const byName=new Map(actual.map(p=>[p.name,p.stars]));ps=palNames.map(n=>({name:n,stars:[...(byName.get(n)||[])]}));if(!ps[0].stars.length)ps[0].stars=['七殺'];host.hidden=false;host.closest('.result-card')?.classList.add('visual-mode');host.innerHTML=`<div class="chart-intro"><span>互動命盤</span><strong>12 宮 × 主星、輔星及雜曜；先揀宮，再點星</strong></div><div class="ziwei-board">${ps.map((p,i)=>`<button class="palace-card ${i===0?'is-selected':''}" data-index="${i}"><small>${esc(p.name)}${p.name.endsWith('宮')?'':'宮'}</small><strong>${esc(p.stars.slice(0,3).join('、'))}</strong><span>${p.stars.length} 粒星 · 點擊解釋</span></button>`).join('')}</div><div class="palace-detail" id="palaceDetail"></div><div class="term-drawer" id="termDrawer" hidden></div>`;host.querySelectorAll('.palace-card').forEach((c,i)=>c.onclick=()=>show(i));show(0);};
  btn.addEventListener('click',()=>setTimeout(render,100));
})();
